us'] === $value ? 'selected' : '' ?>><?= $label ?></option><?php endforeach ?></select><?php if ($order['status'] === 'dibatalkan'): ?><input type="hidden" name="status" value="dibatalkan"><p class="form-text">Stok telah dikembalikan. Pesanan tidak dapat diaktifkan lagi.</p><?php endif ?></div><div class="mb-3"><label class="form-label" for="status_pembayaran">Status pembayaran</label><select class="form-select" id="status_pembayaran" name="status_pembayaran"><option value="belum_dibayar" <?= $order['status_pembayaran'] === 'belum_dibayar' ? 'selected' : '' ?>>Belum dibayar</option><option value="sudah_dibayar" <?= $order['status_pembayaran'] === 'sudah_dibayar' ? 'selected' : '' ?>>Sudah dibayar</option></select></div><button class="btn btn-primary w-100" type="submit">Simpan Status</button></form></div></div></div>
